@Configuration
@EnableAutoConfiguration
@ComponentScan
@EnableCaching
@EnableSwagger2
@EnableAsync
public class WebAppConfig extends SpringBootServletInitializer {

    private static final Class<WebAppConfig> APP_CLASS = WebAppConfig.class;

    @Override
    protected SpringApplicationBuilder configure(SpringApplicationBuilder application) {
        return application.sources(APP_CLASS);
    }

    public static void main(String[] args) throws IOException {
        SpringApplication.run(APP_CLASS, args);
    }

    @Bean
    public EmbeddedServletContainerCustomizer containerCustomizer() {
        return new EmbeddedServletContainerCustomizer() {
            @Override
            public void customize(ConfigurableEmbeddedServletContainer container) {
                Integer port;
                try {
                    port = Integer.valueOf(System.getenv("PORT"));
                } catch (NumberFormatException ex) {
                    port = 8080;
                }
                container.setPort(port);
            }
        };
    }

    @Bean
    public CorsFilter corsFilter() {
        UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();
        CorsConfiguration config = new CorsConfiguration();
        config.setAllowCredentials(true); // you USUALLY want this
        config.addAllowedOrigin("*");
        config.addAllowedHeader("*");
        config.addAllowedMethod("GET");
        config.addAllowedMethod("POST");
        config.addAllowedMethod("DELETE");
        config.addAllowedMethod("PUT");
        source.registerCorsConfiguration("/**", config);
        return new CorsFilter(source);
    }

    @Bean
    public Gson gson() {
        return new GsonBuilder().setExclusionStrategies(new AnnotationExclusionStrategy()).create();
    }

    @Bean
    public Docket api() {
        return new Docket(DocumentationType.SWAGGER_2)
                .select()
                .apis(RequestHandlerSelectors.any())
                .paths(PathSelectors.any())
                .build();
    }

    @Bean
    public NotificationManager notificationSubscriptions() {
        return new NotificationManager();
    }
}

public class NgrokConfig {
    private static String PATH_TO_URL = "/tmp/externalURL";
    private static String EXTERNAL_URL = "NOTDEF";

    public static String getExternalUrl() throws IOException {
        if(EXTERNAL_URL.equals("NOTDEF")) {
            BufferedReader reader = null;

            try {
                File file = new File(PATH_TO_URL);
                reader = new BufferedReader(new FileReader(file));

                String line;
                while ((line = reader.readLine()) != null) {
                    if(line!=null && line.contains("http")) {
                        line = line.trim();
                        EXTERNAL_URL = line;
                        break;
                    }
                }
                return EXTERNAL_URL;

            } catch (IOException e) {
                return null;
            } finally {
                try {
                    reader.close();
                } catch (IOException e) {
                    return null;
                }
            }
        }
        else {
            return EXTERNAL_URL;
        }
    }
}

@Entity
@Table(name = "users")
@Inheritance(strategy = InheritanceType.JOINED)
public abstract class User implements Serializable {

    public static enum Roles {
        ROLE_USER, ROLE_EMPLOYEE, ROLE_MANAGER, ROLE_ADMIN
    }

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    protected long id;
    @Column(name = "username", nullable = false, unique = true)
    protected String username;
    @JsonIgnore
    @Column(name = "password", nullable = false)
    protected String password;
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(
            name = "roles",
            joinColumns = @JoinColumn(name = "user_id")
    )
    @Cascade(CascadeType.ALL)
    protected Set<String> roles;

    public User() {
        this.roles = new HashSet<>();
    }

    public User(String username, String password) {
        this.username = username;
        this.password = password;
        this.roles = new HashSet<>();
    }

    public String getUsername() {
        return username;
    }

    public void setUsername(String username) {
        this.username = username;
    }

    public String getPassword() {
        return password;
    }

    public void setPassword(String password) {
        this.password = password;
    }

    public long getId() {
        return id;
    }

    public void setId(long id) {
        this.id = id;
    }

    public Collection<GrantedAuthority> getRoles() {
        List<GrantedAuthority> authorities = new LinkedList<>();
        for (String a : roles) {
            authorities.add(new SimpleGrantedAuthority(a));
        }
        return authorities;
    }

    public Set<String> getRolesSet() { return this.roles; }

    protected void addRole(String role) {
        this.roles.add(role);
    }

    @Override
    public String toString() {
        return "User{" + "id=" + id + ", username=" + username + ", password=" + password + ", roles=" + roles + '}';
    }

}

