public class NotificationManager {

    private final Logger logger = LoggerFactory.getLogger(WebAppConfig.class);

    @Autowired
    private ConsumerDAO consumers;
    @Autowired
    private NotificationDAO notifications;

    private final Multimap<String, SseEmitter> subscriptions;

    public NotificationManager() {
        this.subscriptions = HashMultimap.create();
    }

    public SseEmitter subscribe(String username) {
        SseEmitter sseEmitter = new SseEmitter(0l);
        sseEmitter.onCompletion(new DeleteTask(this, username, sseEmitter));
        this.subscriptions.put(username, sseEmitter);
        return sseEmitter;
    }

    public void unsubscribe(String username, SseEmitter emitter) {
        this.subscriptions.remove(username, emitter);
    }

    public void sendNotification(String username, Notification notification){
        Consumer consumer = this.consumers.findByUsername(username);
        notification = notifications.save(notification);
        consumer.addNotifications(notification);
        consumers.save(consumer);

        if (this.subscriptions.containsKey(username)) {
            for (SseEmitter sse : this.subscriptions.get(username)) {
                try {
                    sse.send(notification, MediaType.APPLICATION_JSON);
                } catch (IOException ex) {
                    this.logger.warn("Broken SSE Emitter..discarding it...");
                }
            }
        }
    }

    public void removeNotification(long notificationId) {
        notifications.delete(notificationId);
    }

    public void readNotification(long notificationId) {
        Notification n = notifications.findById(notificationId);
        n.setReadStatus(true);
        notifications.save(n);
    }
}

class DeleteTask implements Runnable {

    private final Logger logger = LoggerFactory.getLogger(WebAppConfig.class);
    private NotificationManager notifications;
    private String username;
    private SseEmitter sse;

    public DeleteTask(NotificationManager notifications, String username, SseEmitter sse) {
        this.notifications = notifications;
        this.username = username;
        this.sse = sse;
    }

    @Override
    public void run() {
        this.logger.info(username + " disconnected!");
        this.notifications.unsubscribe(username, sse);
    }

}

public class AnnotationExclusionStrategy implements ExclusionStrategy {

    @Override
    public boolean shouldSkipField(FieldAttributes f) {
        return f.getAnnotation(Exclude.class) != null;
    }

    @Override
    public boolean shouldSkipClass(Class<?> clazz) {
        return false;
    }
}

@Entity
@Table(name = "printing_schemas")
public class PrintingSchema {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private long id;

    @Column(name = "pschema_name", nullable = false)
    private String name;

    @Column(name = "paper_specs", nullable = false)
    private String paperSpecs;

    @Column(name = "binding_specs", nullable = true)
    private String bindingSpecs;

    @Column(name = "cover_specs", nullable = true)
    private String coverSpecs;

    @Column(name = "is_deleted", nullable = false)
    private boolean deleted;

    public PrintingSchema() {}

    public PrintingSchema(PrintingSchema ps) {
        this.name = ps.getName();
        this.paperSpecs = ps.getPaperSpecs();
        this.bindingSpecs = ps.getBindingSpecs();
        this.coverSpecs = ps.getCoverSpecs();
        this.deleted = false;
    }

    public PrintingSchema(String name, String paperSpecs, String bindingSpecs, String coverSpecs) {
        this.name = name;
        this.paperSpecs = paperSpecs;
        this.bindingSpecs = bindingSpecs;
        this.coverSpecs = coverSpecs;
        this.deleted = false;
    }

    public PrintingSchema(String name , PaperItem psi, BindingItem bi, CoverItem ci) {
        this.name = name;
        this.paperSpecs = psi.genKey(); // Always required paperSpecs
        if(bi!=null) {
            this.bindingSpecs = bi.genKey();
            if(ci!=null) {
                this.coverSpecs = ci.genKey();
            } else {
                this.coverSpecs = "";
            }
        } else if(bi.getRingsType().equals(Item.RingType.BINDING.toString())) {
            bi.setRingThicknessInfLim(0);
            bi.setRingThicknessSupLim(0);
            this.bindingSpecs = BindingItem.RingType.STAPLING.toString();
        } else {
            this.bindingSpecs="";
        }
        this.deleted = false;
    }

    public long getId() { return id; }

    public String getName() { return name; }

    public void setName(String name) { this.name = name; }

    public String getPaperSpecs() {
        if(paperSpecs!=null) return paperSpecs;
        else return "";
    }

    public void setPaperSpecs(String paperSpecs) { this.paperSpecs = paperSpecs; }

    public String getBindingSpecs() {
        if(bindingSpecs!=null) return bindingSpecs;
        else return "";
    }

    public void setBindingSpecs(String bindingSpecs) { this.bindingSpecs = bindingSpecs; }

    public String getCoverSpecs() {
        if(coverSpecs!=null) return coverSpecs;
        else return "";
    }

    public void setCoverSpecs(String coverSpecs) { this.coverSpecs = coverSpecs; }

    public boolean isDeleted() { return this.deleted; }

    public void delete() { this.deleted=true; }

    /**
     * Converts the string paperSpecs to its respective PaperItem Object.
     * @return a PaperItem
     */
    public PaperItem getPaperItem() {
        ItemFactory itemf = new ItemFactory();
        return (PaperItem) itemf.createItem(this.paperSpecs);
    }

    /**
     * Converts the string bindingSpecs to its respective PaperItem Object.
     * @return a BindingItem
     */
    public BindingItem getBindingItem() {
        ItemFactory itemf = new ItemFactory();
        return (BindingItem) itemf.createItem(this.bindingSpecs);
    }

    /**
     * Converts the string coverSpecs to its respective CoverItem Object.
     * @return CoverItem
     */
    public CoverItem getCoverItem() {
        ItemFactory itemf = new ItemFactory();
        return (CoverItem) itemf.createItem(this.coverSpecs);
    }


    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof PrintingSchema)) return false;

        PrintingSchema that = (PrintingSchema) o;

        if (getId() != that.getId()) return false;
        if (getName() != null ? !getName().equals(that.getName()) : that.getName() != null) return false;
        if (getPaperSpecs() != null ? !getPaperSpecs().equals(that.getPaperSpecs()) : that.getPaperSpecs() != null)
            return false;
        if (getBindingSpecs() != null ? !getBindingSpecs().equals(that.getBindingSpecs()) : that.getBindingSpecs() != null)
            return false;
        return getCoverSpecs() != null ? getCoverSpecs().equals(that.getCoverSpecs()) : that.getCoverSpecs() == null;

    }

    @Override
    public int hashCode() {
        int result = (int) (getId() ^ (getId() >>> 32));
        result = 31 * result + (getName() != null ? getName().hashCode() : 0);
        result = 31 * result + (getPaperSpecs() != null ? getPaperSpecs().hashCode() : 0);
        result = 31 * result + (getBindingSpecs() != null ? getBindingSpecs().hashCode() : 0);
        result = 31 * result + (getCoverSpecs() != null ? getCoverSpecs().hashCode() : 0);
        return result;
    }

    @Override
    public String toString() {
        return "PrintingSchema{" +
                "id=" + id +
                ", name='" + name + '\'' +
                ", paperSpecs='" + paperSpecs + '\'' +
                ", bindingSpecs='" + bindingSpecs + '\'' +
                ", coverSpecs='" + coverSpecs + '\'' +
                '}';
    }

    public String getPresentationString(String range) {
        StringBuilder sb = new StringBuilder();

        String[] psecs = this.paperSpecs.split(",");
        sb.append(range);
        sb.append(" - Cor: ");

        switch (psecs[1]){
            case "COLOR" :
                sb.append("A cores");
                break;
            case "GREY_TONES" :
                sb.append("Tons de Cinza");
                break;
            case "BW" :
                sb.append("Preto e Branco");
                break;
        }

        sb.append(" + Formato: " + psecs[2]);

        switch (psecs[3]){
            case "DUPLEX" :
                sb.append(", Frente e Verso");
                break;
            case "SIMPLEX" :
                sb.append(", Frente");
                break;
        }

        if(this.bindingSpecs!=null && !this.bindingSpecs.equals("")) {

            String[] bspecs = this.bindingSpecs.split(",");

            switch (bspecs[0]){
                case "STAPLING" :
                    sb.append(" + Acabamentos: Agrafar");
                    break;
                case "BINDING" :
                    switch (bspecs[1]){
                        case "SPIRAL" :
                            sb.append(" + Acabamentos: Argolas em Espiral");
                            break;
                        case "PLASTIC" :
                            sb.append(" + Acabamentos: Argolas de plástico");
                            break;
                        case "WIRE" :
                            sb.append(" + Acabamentos: Argolas de arame");
                            break;
                        case "STEELMAT" :
                            sb.append(" + Acabamentos: Encadernação térmica");
                            break;
                    }
                    break;
            }
        }

        if(this.coverSpecs!=null && !this.coverSpecs.equals("")) {

            String[] cspecs = this.coverSpecs.split(",");

            switch (cspecs[1]){
                case "CRISTAL_ACETATE" :
                    sb.append(" + Capa: Acetato em cristal");
                    break;
                case "PVC_TRANSPARENT" :
                    sb.append(" + Capa: PVC transparente fosco");
                    break;
                case "PVC_OPAQUE" :
                    sb.append(" + Capa: PVC opaco");
                    break;
            }
        }

        return sb.toString();
    }
}

@Embeddable
public class Money {
    private static int MONEY_CEIL = 100;

    @Column(name = "balance_currency", nullable = false)
    private String currency;

    @Column(name = "balance_integer_part", nullable = false)
    private int integerPart;

    @Column(name = "balance_fractional_part", nullable = false)
    private int fractionalPart;

    public Money() {
        this.currency="EUR";
        this.integerPart=0;
        this.fractionalPart=0;
    }

    public Money(int integerPart, int fractionalPart) {
        this.currency="EUR";
        this.integerPart = integerPart;
        this.fractionalPart = fractionalPart;
    }

    public Money(String currency, int integerPart, int fractionalPart) {
        this.currency = currency;
        this.integerPart = integerPart;
        this.fractionalPart = fractionalPart;
    }

    public String getCurrency() { return currency; }

    public void setCurrency(String currency) { this.currency = currency; }

    public int getIntegerPart() { return integerPart; }

    public void setIntegerPart(int integerPart) { this.integerPart = integerPart; }

    public int getFractionalPart() { return fractionalPart; }

    public void setFractionalPart(int fractionalPart) { this.fractionalPart = fractionalPart; }

    public void addMoney(Money m) {
        this.integerPart += m.getIntegerPart();
        int tmp = this.fractionalPart + m.getFractionalPart();

        if(tmp >= MONEY_CEIL) {
            while(tmp >= MONEY_CEIL) {
                this.integerPart++;
                this.fractionalPart = tmp - MONEY_CEIL;
                tmp -= MONEY_CEIL;
            }
        } else {
            this.fractionalPart = tmp;
        }
    }

    public void subtractMoney(Money m) {
        this.integerPart -= m.getIntegerPart();
        int tmp = this.fractionalPart - m.getFractionalPart();

        if(tmp <= 0) {
            while(tmp <= 0) {
                this.integerPart--;
                this.fractionalPart = tmp + MONEY_CEIL;
                tmp += MONEY_CEIL;
            }
        } else {
            this.fractionalPart = tmp;
        }
    }

    public void addQuantity(int ip, int fp) {
        this.addMoney(new Money(ip,fp));
    }

    public void subtractQuantity(int ip, int fp) {
        this.subtractMoney(new Money(ip,fp));
    }

    public void addDoubleQuantity(double value) {
        value = round(value,2);
        String tmp[] = String.valueOf(value).split("\\.");
        this.addMoney(new Money(Integer.parseInt(tmp[0]), Integer.parseInt(tmp[1])));
    }

    public void subtractDoubleQuantity(double value) {
        value = round(value,2);
        String tmp[] = String.valueOf(value).split("\\.");
        this.subtractMoney(new Money(Integer.parseInt(tmp[0]), Integer.parseInt(tmp[1])));
    }

    private double round(double value, int places) {
        if (places < 0) throw new IllegalArgumentException();

        long factor = (long) Math.pow(10, places);
        value = value * factor;
        long tmp = Math.round(value);
        return (double) tmp / factor;
    }

    public String getMoneyAsString(String separator) {
        if(separator!=null) {
            return (this.integerPart+separator.trim()+this.fractionalPart);
        } else {
            return "";
        }
    }

    public double getMoneyAsDouble() {
        return Double.parseDouble(String.valueOf(this.integerPart)+"."+String.valueOf(this.getFractionalPart()));
    }

    public boolean isValid() {
        return (this.fractionalPart < MONEY_CEIL);
    }
}

