        int totalReviews = this.reviews.size();
        if(totalReviews > 1) {
            int sumRatins = 0;
            for (Review rev : this.reviews) {
                sumRatins += rev.getRating();
            }
            this.avgRating = (sumRatins / totalReviews);
        } else {
            Review only=null;
            for (Review rev : this.reviews) {
