        PaperItem p1 = new PaperItem(Item.Format.A4, Item.Sides.DUPLEX, Item.Colors.BW);
        PrintingSchema tmpschema = new PrintingSchema("A4+2LAD+PB", p1.genKey(), "BINDING,STAPLING,0,0", "");
