    private String priceA4DUPLEX;
    private String priceA3SIMPLEX;
    private String priceA3DUPLEX;

    public PaperTableItem() {
        super();
    }

    public PaperTableItem(int infLim, int supLim) {
        super();
        this.infLim = infLim;
        this.supLim = supLim;
        this.priceA4SIMPLEX = DEFAULT;
        this.priceA4DUPLEX = DEFAULT;
        this.priceA3SIMPLEX = DEFAULT;
        this.priceA3DUPLEX = DEFAULT;
    }

    public int getInfLim() {
        return infLim;
    }

    public void setInfLim(int infLim) {
        this.infLim = infLim;
    }

    public int getSupLim() {
        return supLim;
    }

    public void setSupLim(int supLim) {
        this.supLim = supLim;
    }

    public String getPriceA4SIMPLEX() {
        return priceA4SIMPLEX;
    }

    public void setPriceA4SIMPLEX(String priceA4SIMPLEX) {
        this.priceA4SIMPLEX = priceA4SIMPLEX;
    }

    public String getPriceA4DUPLEX() {
        return priceA4DUPLEX;
    }

    public void setPriceA4DUPLEX(String priceA4DUPLEX) {
        this.priceA4DUPLEX = priceA4DUPLEX;
    }

    public String getPriceA3SIMPLEX() {
        return priceA3SIMPLEX;
    }

    public void setPriceA3SIMPLEX(String priceA3SIMPLEX) {
        this.priceA3SIMPLEX = priceA3SIMPLEX;
    }

    public String getPriceA3DUPLEX() {
        return priceA3DUPLEX;
    }

    public void setPriceA3DUPLEX(String priceA3DUPLEX) {
        this.priceA3DUPLEX = priceA3DUPLEX;
    }

    public String getColors() { return colors; }

    public void setColors(String colors) { this.colors = colors; }

    public String genKey() {
        return this.infLim+";"+this.supLim;
    }

    // Add new cost to the PaperTableItem instance
    public void addPriceToPaperTableItem(PaperItem pi, float price) {
        String paperSpecs = pi.getPaperSpecs();

        // Format+Sides
        if(paperSpecs.equals(A4Simplex)) {
            this.priceA4SIMPLEX = String.valueOf(price);
        } else if(paperSpecs.equals(A4Duplex)) {
            this.priceA4DUPLEX = String.valueOf(price);
        } if(paperSpecs.equals(A3Simplex)) {
            this.priceA3SIMPLEX = String.valueOf(price);
        } if(paperSpecs.equals(A3Duplex)) {
            this.priceA3DUPLEX = String.valueOf(price);
        }
    }

    @Override
    public int compareTo(PaperTableItem pti) {
        if(pti.getSupLim() > this.getSupLim()) return -1;
        else return 1;
    }
}

@Embeddable
public class Money {
    private static int MONEY_CEIL = 100;

    @Column(name = "balance_currency", nullable = false)
    private String currency;

    @Column(name = "balance_integer_part", nullable = false)
    private int integerPart;

    @Column(name = "balance_fractional_part", nullable = false)
    private int fractionalPart;

    public Money() {
        this.currency="EUR";
        this.integerPart=0;
        this.fractionalPart=0;
    }

    public Money(int integerPart, int fractionalPart) {
        this.currency="EUR";
        this.integerPart = integerPart;
        this.fractionalPart = fractionalPart;
    }

    public Money(String currency, int integerPart, int fractionalPart) {
        this.currency = currency;
        this.integerPart = integerPart;
        this.fractionalPart = fractionalPart;
    }

    public String getCurrency() { return currency; }

    public void setCurrency(String currency) { this.currency = currency; }

    public int getIntegerPart() { return integerPart; }

    public void setIntegerPart(int integerPart) { this.integerPart = integerPart; }

    public int getFractionalPart() { return fractionalPart; }

    public void setFractionalPart(int fractionalPart) { this.fractionalPart = fractionalPart; }

    public void addMoney(Money m) {
        this.integerPart += m.getIntegerPart();
        int tmp = this.fractionalPart + m.getFractionalPart();

        if(tmp >= MONEY_CEIL) {
            while(tmp >= MONEY_CEIL) {
                this.integerPart++;
                this.fractionalPart = tmp - MONEY_CEIL;
                tmp -= MONEY_CEIL;
            }
        } else {
            this.fractionalPart = tmp;
        }
    }

    public void subtractMoney(Money m) {
        this.integerPart -= m.getIntegerPart();
        int tmp = this.fractionalPart - m.getFractionalPart();

        if(tmp <= 0) {
            while(tmp <= 0) {
                this.integerPart--;
                this.fractionalPart = tmp + MONEY_CEIL;
                tmp += MONEY_CEIL;
            }
        } else {
            this.fractionalPart = tmp;
        }
    }

    public void addQuantity(int ip, int fp) {
        this.addMoney(new Money(ip,fp));
    }

    public void subtractQuantity(int ip, int fp) {
        this.subtractMoney(new Money(ip,fp));
    }

    public void addDoubleQuantity(double value) {
        value = round(value,2);
        String tmp[] = String.valueOf(value).split("\\.");
        this.addMoney(new Money(Integer.parseInt(tmp[0]), Integer.parseInt(tmp[1])));
    }

    public void subtractDoubleQuantity(double value) {
        value = round(value,2);
        String tmp[] = String.valueOf(value).split("\\.");
        this.subtractMoney(new Money(Integer.parseInt(tmp[0]), Integer.parseInt(tmp[1])));
    }

    private double round(double value, int places) {
        if (places < 0) throw new IllegalArgumentException();

        long factor = (long) Math.pow(10, places);
        value = value * factor;
        long tmp = Math.round(value);
        return (double) tmp / factor;
    }

    public String getMoneyAsString(String separator) {
        if(separator!=null) {
            return (this.integerPart+separator.trim()+this.fractionalPart);
        } else {
            return "";
        }
    }

    public double getMoneyAsDouble() {
        return Double.parseDouble(String.valueOf(this.integerPart)+"."+String.valueOf(this.getFractionalPart()));
    }

    public boolean isValid() {
        return (this.fractionalPart < MONEY_CEIL);
    }
}

public abstract class Item {

    public static String PAPER = "PAPER";
    public static String COVER = "COVER";

    public static String checkItemType(String item) {
        String[] chunks = item.split(",");
        if (chunks[0] != null && (chunks[0].equals(PAPER) || chunks[0].equals(COVER) || chunks[0].equals(Item.RingType.BINDING.toString()))) {
            return chunks[0];
        }
        return "";
    }

    // Paper
    public static enum Format {
        A4, A3
    }

    public static enum Sides {
        SIMPLEX, DUPLEX
    }

    public static enum Colors {
        BW, GREY_TONES, COLOR
    }

    // Cover
    public static enum CoverType {
        CRISTAL_ACETATE, PVC_TRANSPARENT, PVC_OPAQUE
    }

    // Binding
    public static enum RingType {
        PLASTIC, SPIRAL, WIRE, STEELMAT, STAPLING, BINDING
    }

    public Item() {
    }

    /**
     * Generates a key which identifies (and describes) a certain item.
     *
     * @return the key which identifies the item by the
     * concatenation of its characteristics.
     */
    public abstract String genKey();

}

public class ItemFactory {

    public ItemFactory(){}

    /**
     * Create a concrete instance of an item.
     * @param item, String that represents the item specs as stored in the database
     *              or as its received from front-end applications
     * @return A concrete instance of the Item derived from the input String
     * which is parsed along the function cut in pieces and feeded to the returned object.
     */
    public Item createItem(String item) {
        String itemType;

        String[] parts = item.split(",");
        itemType = parts[0];

        if(itemType.equals(RangePaperItem.KEY_BASE)) {
            PaperItem.Colors colors;
            PaperItem.Format format;
            PaperItem.Sides sides;

            colors = PaperItem.Colors.valueOf(parts[1]);
            format = PaperItem.Format.valueOf(parts[2]);
            sides = PaperItem.Sides.valueOf(parts[3]);

            if(parts.length > 4 && parts[4]!=null && parts[5]!=null) {
                int infLim, supLim;
                infLim = Integer.parseInt(parts[4]);
                supLim = Integer.parseInt(parts[5]);
                return new RangePaperItem(format, sides, colors, infLim, supLim);
            } else {
                return new PaperItem(format,sides,colors);
            }
        }
        else if(itemType.equals(BindingItem.KEY_BASE)) {
            BindingItem.RingType ringsType;

            ringsType = BindingItem.RingType.valueOf(parts[1]);
            if(parts.length > 3 && parts[2]!=null && parts[3]!=null) {
                int infLim, supLim;
                infLim = Integer.parseInt(parts[2]);
                supLim = Integer.parseInt(parts[3]);
                return new BindingItem(ringsType,infLim,supLim);
            } else {
                return new BindingItem(ringsType,0,0);
            }

        }
        else if(itemType.equals(CoverItem.KEY_BASE)) {
            CoverItem.CoverType coverType;

            coverType = CoverItem.CoverType.valueOf(parts[1]);
            if(parts.length > 2 && parts[2]!=null) {
                PaperItem.Format format = PaperItem.Format.valueOf(parts[2]);
                return new CoverItem(coverType,format);
            } else {
                // by default create an A4 cover
                return new CoverItem(coverType,PaperItem.Format.A4);
            }
        }

        return null;
    }

    /**
     * Convert a PaperTableItem to its respective PriceItems
     * @param pti, a new entry in the price table
     * @return List<RangePaperItem>, List of price items which result from the conversion.
     */
    public List<RangePaperItem> fromPaperTableItemToPaperItems(PaperTableItem pti) {
        List<RangePaperItem> res = new ArrayList<>();

        if(!pti.getPriceA4SIMPLEX().equals(PaperTableItem.DEFAULT)) {
            res.add(new RangePaperItem(PaperItem.Format.A4, PaperItem.Sides.SIMPLEX, PaperItem.Colors.valueOf(pti.getColors()), pti.getInfLim(), pti.getSupLim()));
        }
        if(!pti.getPriceA4DUPLEX().equals(PaperTableItem.DEFAULT)) {
            res.add(new RangePaperItem(PaperItem.Format.A4, PaperItem.Sides.DUPLEX, PaperItem.Colors.valueOf(pti.getColors()), pti.getInfLim(), pti.getSupLim()));
        }
        if(!pti.getPriceA3SIMPLEX().equals(PaperTableItem.DEFAULT)) {
            res.add(new RangePaperItem(PaperItem.Format.A3, PaperItem.Sides.SIMPLEX, PaperItem.Colors.valueOf(pti.getColors()), pti.getInfLim(), pti.getSupLim()));
        }
        if(!pti.getPriceA3DUPLEX().equals(PaperTableItem.DEFAULT)) {
            res.add(new RangePaperItem(PaperItem.Format.A3, PaperItem.Sides.DUPLEX, PaperItem.Colors.valueOf(pti.getColors()), pti.getInfLim(), pti.getSupLim()));
        }

        return res;
    }
}

public class PaperItem extends Item {
    public static String KEY_BASE = "PAPER";

    protected Format format;
    protected Sides sides;
    protected Colors colors;

    public PaperItem(Format format, Sides sides, Colors colors) {
        this.format = format;
        this.sides = sides;
        this.colors = colors;
    }

    public Format getFormat() {
        return format;
    }

    public void setFormat(Format format) {
        this.format = format;
    }

    public Sides getSides() {
        return sides;
    }

    public void setSides(Sides sides) {
        this.sides = sides;
    }

    public Colors getColors() {
        return colors;
    }

    public void setColors(Colors colors) {
        this.colors = colors;
    }

    // Get the paper specs hash
    public String getPaperSpecs() {
        return this.format.toString()+this.sides.toString();
    }

    @Override
    public String genKey() {
        return String.format("%s,%s,%s,%s", KEY_BASE, colors.toString(), format.toString(), sides.toString());
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof PaperItem)) return false;

        PaperItem paperItem = (PaperItem) o;

        if (getFormat() != paperItem.getFormat()) return false;
        if (getSides() != paperItem.getSides()) return false;
        return getColors() == paperItem.getColors();

    }

    @Override
    public int hashCode() {
        int result = getFormat() != null ? getFormat().hashCode() : 0;
        result = 31 * result + (getSides() != null ? getSides().hashCode() : 0);
        result = 31 * result + (getColors() != null ? getColors().hashCode() : 0);
        return result;
    }
}

public class RangePaperItem extends PaperItem {
    private int infLim;
    private int supLim;

    public RangePaperItem(Format format, Sides sides, Colors colors, int infLim, int supLim) {
        super(format,sides,colors);
        this.infLim = infLim;
        this.supLim = supLim;
    }

    public int getInfLim() {
        return infLim;
    }

    public void setInfLim(int infLim) {
        this.infLim = infLim;
    }

    public int getSupLim() {
        return supLim;
    }

    public void setSupLim(int supLim) {
        this.supLim = supLim;
    }

    @Override
    public String genKey() {
        return String.format("%s,%s,%s,%s,%d,%d",KEY_BASE, this.colors, this.format, this.sides, infLim, supLim);
    }

}

