            return false;
        }
        if (getLongitude() != null ? !getLongitude().equals(printShop.getLongitude()) : printShop.getLongitude() != null) {
            return false;
        }
        if (getNif() != null ? !getNif().equals(printShop.getNif()) : printShop.getNif() != null) {
