            APIContext apiContext = new APIContext(accessToken);
            batch = payout.createSynchronous(apiContext);

            LoggingManager.info(this.getClass(), "Payout Batch Processed with ID: " + batch.getBatchHeader().getPayoutBatchId());

            if (batch != null) {
