     * Calculate budgets for a given list of printshops.
     *
     * @param pshops printshops to calculate the budget.
     * @return A map containing the printshopID associated with the calculated
     * budget
     */
    public Map<Long, String> calcBudgetsForPrintShops(List<PrintShop> pshops) {
        Map<Long, String> budgets = new HashMap<>();

        Set<Document> prDocs = this.getDocuments();
        for (PrintShop printShop : pshops) {
            BudgetCalculator budgetCalculator = new BudgetCalculator(printShop);
            float totalCost = 0; // In the future we may specifie the budget by file its easy!
            for (Document document : prDocs) {
                for (DocumentSpec documentSpec : document.getSpecs()) {
                    float specCost = 0;
                    if (documentSpec.getFirstPage() != 0 && documentSpec.getLastPage() != 0) {
                        // Partial calculation
                        specCost = budgetCalculator.calculatePrice(documentSpec.getFirstPage(), documentSpec.getLastPage(), documentSpec.getPrintingSchema());
                    } else {
                        // Total calculation
                        System.out.println(document.getTotalPages());
                        specCost = budgetCalculator.calculatePrice(1, document.getTotalPages(), documentSpec.getPrintingSchema());
                    }
                    if (specCost != -1) {
                        totalCost += specCost;
                    } else {
                        budgets.put(printShop.getId(), "Esta reprografia não pode satisfazer o pedido.");
                    }
                }
            }
            if (totalCost > 0) {
                NumberFormat nf = NumberFormat.getNumberInstance(Locale.US);
                DecimalFormat df = (DecimalFormat) nf;
                df.setMaximumFractionDigits(2);
                budgets.put(printShop.getId(), String.valueOf(df.format(totalCost))); // add to budgets
            }
        }

        return budgets;
    }
}

public abstract class Item {

    public static String PAPER = "PAPER";
    public static String COVER = "COVER";

    public static String checkItemType(String item) {
        String[] chunks = item.split(",");
        if (chunks[0] != null && (chunks[0].equals(PAPER) || chunks[0].equals(COVER) || chunks[0].equals(Item.RingType.BINDING.toString()))) {
            return chunks[0];
        }
        return "";
    }

    // Paper
    public static enum Format {
        A4, A3
    }

    public static enum Sides {
        SIMPLEX, DUPLEX
    }

    public static enum Colors {
        BW, GREY_TONES, COLOR
    }

    // Cover
    public static enum CoverType {
        CRISTAL_ACETATE, PVC_TRANSPARENT, PVC_OPAQUE
    }

    // Binding
    public static enum RingType {
        PLASTIC, SPIRAL, WIRE, STEELMAT, STAPLING, BINDING
    }

    public Item() {
    }

    /**
     * Generates a key which identifies (and describes) a certain item.
     *
     * @return the key which identifies the item by the
     * concatenation of its characteristics.
     */
    public abstract String genKey();

}

public class ItemFactory {

    public ItemFactory(){}

    /**
     * Create a concrete instance of an item.
     * @param item, String that represents the item specs as stored in the database
     *              or as its received from front-end applications
     * @return A concrete instance of the Item derived from the input String
     * which is parsed along the function cut in pieces and feeded to the returned object.
     */
    public Item createItem(String item) {
        String itemType;

        String[] parts = item.split(",");
        itemType = parts[0];

        if(itemType.equals(RangePaperItem.KEY_BASE)) {
            PaperItem.Colors colors;
            PaperItem.Format format;
            PaperItem.Sides sides;

            colors = PaperItem.Colors.valueOf(parts[1]);
            format = PaperItem.Format.valueOf(parts[2]);
            sides = PaperItem.Sides.valueOf(parts[3]);

            if(parts.length > 4 && parts[4]!=null && parts[5]!=null) {
                int infLim, supLim;
                infLim = Integer.parseInt(parts[4]);
                supLim = Integer.parseInt(parts[5]);
                return new RangePaperItem(format, sides, colors, infLim, supLim);
            } else {
                return new PaperItem(format,sides,colors);
            }
        }
        else if(itemType.equals(BindingItem.KEY_BASE)) {
            BindingItem.RingType ringsType;

            ringsType = BindingItem.RingType.valueOf(parts[1]);
            if(parts.length > 3 && parts[2]!=null && parts[3]!=null) {
                int infLim, supLim;
                infLim = Integer.parseInt(parts[2]);
                supLim = Integer.parseInt(parts[3]);
                return new BindingItem(ringsType,infLim,supLim);
            } else {
                return new BindingItem(ringsType,0,0);
            }

        }
        else if(itemType.equals(CoverItem.KEY_BASE)) {
            CoverItem.CoverType coverType;

            coverType = CoverItem.CoverType.valueOf(parts[1]);
            if(parts.length > 2 && parts[2]!=null) {
                PaperItem.Format format = PaperItem.Format.valueOf(parts[2]);
                return new CoverItem(coverType,format);
            } else {
                // by default create an A4 cover
                return new CoverItem(coverType,PaperItem.Format.A4);
            }
        }

        return null;
    }

    /**
     * Convert a PaperTableItem to its respective PriceItems
     * @param pti, a new entry in the price table
     * @return List<RangePaperItem>, List of price items which result from the conversion.
     */
    public List<RangePaperItem> fromPaperTableItemToPaperItems(PaperTableItem pti) {
        List<RangePaperItem> res = new ArrayList<>();

        if(!pti.getPriceA4SIMPLEX().equals(PaperTableItem.DEFAULT)) {
            res.add(new RangePaperItem(PaperItem.Format.A4, PaperItem.Sides.SIMPLEX, PaperItem.Colors.valueOf(pti.getColors()), pti.getInfLim(), pti.getSupLim()));
        }
        if(!pti.getPriceA4DUPLEX().equals(PaperTableItem.DEFAULT)) {
            res.add(new RangePaperItem(PaperItem.Format.A4, PaperItem.Sides.DUPLEX, PaperItem.Colors.valueOf(pti.getColors()), pti.getInfLim(), pti.getSupLim()));
        }
        if(!pti.getPriceA3SIMPLEX().equals(PaperTableItem.DEFAULT)) {
            res.add(new RangePaperItem(PaperItem.Format.A3, PaperItem.Sides.SIMPLEX, PaperItem.Colors.valueOf(pti.getColors()), pti.getInfLim(), pti.getSupLim()));
        }
        if(!pti.getPriceA3DUPLEX().equals(PaperTableItem.DEFAULT)) {
            res.add(new RangePaperItem(PaperItem.Format.A3, PaperItem.Sides.DUPLEX, PaperItem.Colors.valueOf(pti.getColors()), pti.getInfLim(), pti.getSupLim()));
        }

        return res;
    }
}

public class PaperItem extends Item {
    public static String KEY_BASE = "PAPER";

    protected Format format;
    protected Sides sides;
    protected Colors colors;

    public PaperItem(Format format, Sides sides, Colors colors) {
        this.format = format;
        this.sides = sides;
        this.colors = colors;
    }

    public Format getFormat() {
        return format;
    }

    public void setFormat(Format format) {
        this.format = format;
    }

    public Sides getSides() {
        return sides;
    }

    public void setSides(Sides sides) {
        this.sides = sides;
    }

    public Colors getColors() {
        return colors;
    }

    public void setColors(Colors colors) {
        this.colors = colors;
    }

    // Get the paper specs hash
    public String getPaperSpecs() {
        return this.format.toString()+this.sides.toString();
    }

    @Override
    public String genKey() {
        return String.format("%s,%s,%s,%s", KEY_BASE, colors.toString(), format.toString(), sides.toString());
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof PaperItem)) return false;

        PaperItem paperItem = (PaperItem) o;

        if (getFormat() != paperItem.getFormat()) return false;
        if (getSides() != paperItem.getSides()) return false;
        return getColors() == paperItem.getColors();

    }

    @Override
    public int hashCode() {
        int result = getFormat() != null ? getFormat().hashCode() : 0;
        result = 31 * result + (getSides() != null ? getSides().hashCode() : 0);
        result = 31 * result + (getColors() != null ? getColors().hashCode() : 0);
        return result;
    }
}

