                break;
            case "SIMPLEX" :
                sb.append(", Frente");
                break;
        }

        if(this.bindingSpecs!=null && !this.bindingSpecs.equals("")) {

            String[] bspecs = this.bindingSpecs.split(",");

            switch (bspecs[0]){
